true}, "primary_location": {"id": "doi:10.1016/j.physrep.2023.10.005", "doi": "https://doi.org/10.1016/j.physrep.2023.10.005", "is_oa": true, "landing_page_url": "https://doi.org/10.1016/j.physrep.2023.10.005", "pdf_url": null, "source": {"id": "https://openalex.org/S48633963", "display_name": "Physics Reports", "issn_l": "0370-1573", "issn": ["0370-1573", "1873-6270"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["cwts-core", "dongbi-b", "jufo-3", "norway-2", "poland-200", "russia-white-list-1"], "host_organization": "https://openalex.org/P4310320990", "host_organization_name": "Elsevier BV", "host_organization_lineage": ["https://openalex.org/P4310320990"], "host_organization_lineage_names": ["Elsevier BV"], "type": "journal"}, "license": "cc-by-nc-nd", "license_id": "https://openalex.org/licenses/cc-by-nc-nd", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Physics Reports", "raw_type": "journal-article"}, "abstract": "Physics is a field of science that has traditionally used the scientific method to answer questions about why natural phenomena occur and to make testable models that explain the phenomena. Discovering equations, laws, and principles that are invariant, robust, and causal has been fundamental in physical sciences throughout the centuries. Discoveries emerge from observing the world and, when possible, performing interventions on the system under study. With the advent of big data and data-driven methods, the fields of causal and equation discovery have developed and accelerated progress in computer science, physics, statistics, philosophy, and many applied fields. This paper reviews the concepts, methods, and relevant works on causal and equation discovery in the broad field of physics and outlines the most important challenges and promising future lines of research. We also provide a taxonomy for data-driven causal and equation discovery, point out connections, and showcase comprehensive case studies in Earth and climate sciences, fluid dynamics and mechanics, and the neurosciences. This review demonstrates that discovering fundamental laws and causal relations by observing natural phenomena is revolutionised with the efficient exploitation of observational data and simulations, modern machine learning algorithms and the combination with domain knowledge. Exciting times are ahead with many challenges and opportunities to improve our understanding of complex systems."}]", "excerpt_truncated": true, "source_sha256": "db7c50149a310318dfce76909db1e9b6c9865a4a11c95c1d4dff6b8f6f4b2a5c", "verification_required": true, "topic_domain": "causal_memory", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2508.11646", "doi:10.1016/j.physrep.2023.10.005", "openalex:W4414458111", "arxiv:2508.11646"], "source_candidates": ["https://doi.org/10.48550/arxiv.2508.11646", "https://arxiv.org/pdf/2508.11646", "https://arxiv.org/abs/2508.11646", "https://doi.org/10.1016/j.physrep.2023.10.005"], "source_candidate_identities": {}}
